// Ambil semua daftar file (6 item) dari node Search sebelumnya
const allFiles = $input.all();

// Pilih 1 nomor file secara acak
const randomIndex = Math.floor(Math.random() * allFiles.length);

// Kirim hanya 1 file terpilih ke node berikutnya
return [allFiles[randomIndex]];

// 1. Ambil teks respons mentah dari AI
const rawContent = $input.first().json.choices[0].message.content;

// 2. Ekstrak HANYA teks yang berada di dalam kurung siku [...] (Array JSON)
// Regex ini akan mengabaikan basa-basi AI di awal atau akhir
const match = rawContent.match(/\[[\s\S]*\]/);

if (!match) {
  throw new Error("Gagal menemukan Array JSON dari respons AI.");
}

const cleanContent = match[0];

// 3. Ubah teks string tadi menjadi Array objek asli
const arraySoal = JSON.parse(cleanContent);

// 4. Kembalikan dalam format n8n agar otomatis terpecah jadi baris terpisah
return arraySoal.map(soal => ({ json: soal }));

